function validate([tasks, space]) {
  if (!Array.isArray(tasks) || tasks.length < 1 || tasks.length > 100000) return 'tasks needs 1 to 10^5 values.';
  if (tasks.some(t => !Number.isInteger(t) || t < 1 || t > 1000000000)) return 'Each task type is an integer from 1 to 10^9.';
  if (!Number.isInteger(space) || space < 1 || space > tasks.length) return 'space is between 1 and tasks.length.';
  return null;
}

