function taskSchedulerII(tasks, space) {
  const lastDay = new Map();
  let day = 0;

  for (const task of tasks) {
    day++;
    if (lastDay.has(task)) {
      const earliest = lastDay.get(task) + space + 1;
      day = Math.max(day, earliest);
    }
    lastDay.set(task, day);
  }
  return day;
}

