function taskSchedulerII(tasks, space) {
  // Walk the calendar one day at a time: do the next job if its type is allowed today, otherwise rest.
  const done = [];
  let next = 0;
  let today = 0;
  while (next < tasks.length) {
    today++;
    let allowed = true;
    for (let k = 0; k < done.length; k++) {
      if (done[k].type === tasks[next] && today - done[k].on <= space) allowed = false;
    }
    if (allowed) {
      done.push({ type: tasks[next], on: today });
      next++;
    }
  }
  return today;
}

