function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const kinds = size === 'large' ? 1 + Math.floor(rand() * 60) : 1 + Math.floor(rand() * 4);
  const pool = Array.from({ length: kinds }, () => rand() < 0.3 ? 1000000000 - Math.floor(rand() * 5) : 1 + Math.floor(rand() * 50));
  const tasks = Array.from({ length: n }, () => pool[Math.floor(rand() * kinds)]);
  const space = 1 + Math.floor(rand() * n);
  return [tasks, space];
}
